{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1724;--card:#0b1220;--accent:#7ce3d6;--muted:#9aa7b2;--glass:rgba(255,255,255,0.04)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6f0ef;background:linear-gradient(180deg,#07121b 0%,#081827 45%,#041018 100%);-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(6px)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;background:linear-gradient(135deg,var(--accent),#5bb5ff);color:#042028;font-weight:700}
    nav a{color:#a9c9c6;text-decoration:none;margin:0 10px;font-weight:600}
    .nav-right{display:flex;align-items:center}
    main{padding:36px 28px;max-width:1100px;margin:0 auto}
    .hero{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:stretch;margin-bottom:28px}
    .hero .lead{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:28px;border-radius:14px;box-shadow:0 6px 30px rgba(2,6,23,0.6)}
    h1{margin:0 0 8px 0;font-size:28px;color:#dff7f2}
    p.lead-desc{margin:0;color:var(--muted);line-height:1.5}
    .pattern-card{background-image:url('assets/img/pattern.svg');background-repeat:no-repeat;background-position:center;background-size:cover;border-radius:14px;padding:22px;color:#042028}
    .meta{display:flex;gap:12px;margin-top:14px}
    .pill{background:var(--glass);padding:8px 10px;border-radius:999px;color:var(--muted);font-weight:600}
    .mood-card{background:linear-gradient(180deg,#062027 0%,#05202a 100%);padding:18px;border-radius:12px;color:#dff7f2}
    .mood-options{display:flex;gap:10px;margin-top:12px}
    .mood-options button{flex:1;padding:10px 12px;border-radius:10px;background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted);cursor:pointer}
    .mood-options button.active{background:linear-gradient(90deg,var(--accent),#6fb8ff);color:#042028;border:0}
    .method-output{margin-top:14px;padding:16px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.03)}
    .cta{display:inline-block;margin-top:14px;padding:12px 16px;border-radius:10px;background:var(--accent);color:#042028;font-weight:700;text-decoration:none}
    section.story{display:flex;gap:20px;margin-top:18px}
    .story p{color:var(--muted);line-height:1.6}
    footer{padding:28px;text-align:center;color:var(--muted);font-size:13px}
    /* playful SVG flourish */
    .flair{height:36px;width:100%;margin-top:12px;opacity:0.9}
    @media(max-width:920px){.hero{grid-template-columns:1fr}.nav-right{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:800;color:#dff7f2">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Events + Cohort sound experiences in {{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav class="nav-right">
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Our Story</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <div class="hero">
      <div class="lead">
        <h1>Sound as a compass — gentle maps for how you feel</h1>
        <p class="lead-desc">We craft guided, cohort-oriented sound gatherings that meet attention where it is. Whether you need a short reset before a big day or a rotating series to steady a seasonal shift, our sessions are designed to land with intention and leave space for your own clarity.</p>
        <div class="meta">
          <div class="pill">Cohort rhythm</div>
          <div class="pill">Small-group focus</div>
          <div class="pill">Practitioner-led</div>
        </div>

        <div class="mood-card">
          <strong style="color:#bff7ef">Not sure where to begin?</strong>
          <div class="mood-options" id="about-mood-options">
            <button data-key="tired">Tired</button>
            <button data-key="busy">Busy</button>
            <button data-key="unstuck">Unstuck</button>
            <button data-key="curious">Curious</button>
          </div>
          <div class="method-output" id="about-method-output">
            <div style="font-weight:700">Try: Gentle Flow — a 45-minute guided cohort wave that blends bowls with breath cues.</div>
            <div style="color:var(--muted);margin-top:8px">This is a small-group setting intended for shared reflection and steady practices. The session suits beginners and regulars.</div>
            <a id="about-cta" class="cta" href="{{PRIMARY_CTA_URL}}">Save a spot</a>
          </div>
        </div>

      </div>

      <div class="pattern-card">
        <svg viewBox="0 0 600 360" class="flair" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid meet">
          <defs>
            <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#7ce3d6" stop-opacity="0.6"/><stop offset="1" stop-color="#6fb8ff" stop-opacity="0.6"/></linearGradient>
          </defs>
          <rect width="600" height="360" rx="16" fill="url(#g1)" opacity="0.08"/>
          <g fill="none" stroke="#c9f7f0" stroke-opacity="0.18" stroke-width="2">
            <path d="M30 300 C120 160, 240 200, 360 120 S540 40, 570 80"/>
            <path d="M0 200 C80 120, 200 140, 320 80 S500 0, 600 40"/>
            <circle cx="420" cy="220" r="34" stroke-opacity="0.12"/>
          </g>
        </svg>
        <h3 style="margin:8px 0;color:#042028">How we design a cohort series</h3>
        <p style="margin:0;color:#08313a">We sequence short iterations — five sessions is a typical WaveSeries — so you and a steady group can notice change without committing to indefinite enrollment.</p>
        <div style="margin-top:12px;color:var(--muted)">Programs are named for their intent: Flow, Reset, and Anchor. Each series includes session notes, a short practice to use between meetings, and a recorded recap for the cohort.</div>
      </div>
    </div>

    <section class="story">
      <div>
        <h3 style="color:#dff7f2">A little on our method</h3>
        <p>We combine tuned bowls, gentle percussive texture, and guided breath cues to shepherd attention. Sessions are intentionally concise — built to recalibrate without extending into ritual pressure. Our cohorts are limited in size so everyone has a guided journey within a held container.</p>
        <p>Pricing and schedules shift with each epoch; we favor short-series passes that reward consistency without creating dependency. If you need private support, we guide you toward one-on-one options.</p>
      </div>
      <div>
        <h3 style="color:#dff7f2">Contraindications & care</h3>
        <p style="color:var(--muted)">Sound immersion is gentle but not suitable for everyone. Please consult with your healthcare provider if you have epilepsy, are pregnant and have concerns, have recent head or inner-ear surgery, or use medical implants. If you have severe anxiety or PTSD, reach out before booking so we can find the right format for you — sometimes a private session or a different practitioner is safer. We will always suggest modifications.</p>
        <p style="color:var(--muted);margin-top:10px">If you take medication that affects heart rate or consciousness, please notify us before arriving. Your safety is our priority.</p>
      </div>
    </section>

  </main>

  <footer>
    <div style="max-width:900px;margin:0 auto">Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}" style="color:#9eeedf">{{EMAIL}}</a>. We hold sessions in {{CITY}}, {{STATE}}. <br>Designed for calm curiosity — not for medical treatment.</div>
  </footer>

  <script>
    ;(function(){
      const options = document.querySelectorAll('#about-mood-options button');
      const out = document.getElementById('about-method-output');
      const cta = document.getElementById('about-cta');
      const map = {
        tired:{label:'Gentle Flow — 45 min',desc:'Slow bowl sequences with longer breath pauses to settle the nervous system.',cta:'Reserve Gentle Flow'},
        busy:{label:'Pulse Pause — 30 min',desc:'A compact cohort reset, focused sounds and grounding cues to interrupt a busy day.',cta:'Book a Pulse Pause'},
        unstuck:{label:'Anchor Series — 5-session Wave',desc:'Short-series format for shifting patterns over several weeks; includes notes and between-session practices.',cta:'Join an Anchor Series'},
        curious:{label:'Exploration Drop-in — 60 min',desc:'A paced session with space for questions and short practices to try different textures.',cta:'Try an Exploration Drop-in'}
      };

      function setMood(key, btn){
        options.forEach(b=>b.classList.remove('active'));
        if(btn) btn.classList.add('active');
        const m = map[key];
        out.querySelector('div').textContent = 'Try: ' + m.label;
        out.querySelector('div').style.fontWeight = '700';
        out.querySelectorAll('div')[1].textContent = m.desc;
        cta.textContent = m.cta;
        cta.href = '{{PRIMARY_CTA_URL}}?focus=' + encodeURIComponent(key);
      }

      options.forEach(btn=>btn.addEventListener('click',()=>setMood(btn.dataset.key,btn)));
      // initialize
      setMood('tired', options[0]);
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071021;--muted:#99b1b0;--accent:#7ce3d6}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#041017 0%,#081323 100%);color:#e8f6f3}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px}
    .logo{font-weight:800;background:linear-gradient(135deg,var(--accent),#6fb8ff);padding:8px 12px;border-radius:8px;color:#042028}
    nav a{color:#bfeee6;margin-left:12px;text-decoration:none;font-weight:600}
    main{max-width:980px;margin:22px auto;padding:0 20px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:20px}
    .faq-card{background:rgba(255,255,255,0.02);padding:18px;border-radius:12px}
    h1{margin:0 0 12px 0}
    details{background:rgba(255,255,255,0.01);border-radius:8px;padding:12px;margin-bottom:10px;border-left:3px solid rgba(124,227,214,0.12)}
    summary{font-weight:700;cursor:pointer}
    .aside{position:sticky;top:24px}
    .small{color:var(--muted);font-size:13px}
    .contra{background:linear-gradient(90deg,#3b1f48,rgba(255,255,255,0.02));padding:12px;border-radius:10px;margin-top:12px}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#042028;font-weight:700;text-decoration:none}
    footer{padding:28px;text-align:center;color:var(--muted)}
    @media(max-width:880px){.grid{grid-template-columns:1fr}.aside{position:static}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">{{BUSINESS_NAME}}</div>
      <div style="font-size:13px;color:#9edfd3">Curated cohort sound gatherings</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Our Story</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <div>
        <h1>Frequently Asked Questions</h1>
        <div class="faq-card">
          <details open>
            <summary>What should I expect at a cohort session?</summary>
            <div class="small">Arrive a few minutes early, settle into a chair or cushion. Sessions begin with a short orientation, move through tuned bowls and guided breath cues, and close with a brief integration period. Come in clothes you can relax in. Hydration and a light meal beforehand are suggested.</div>
          </details>

          <details>
            <summary>How big are the groups?</summary>
            <div class="small">We limit cohorts to a size that lets everyone settle into the work — typically 8–18 people depending on venue. The aim is a held container where the guide can attend to the field without losing intimacy.</div>
          </details>

          <details>
            <summary>What if I’m on medication or have medical concerns?</summary>
            <div class="small">If you take medication that impacts heart rate, consciousness, or balance, consult with your clinician. If you have a diagnosis such as epilepsy, vestibular disorders, recent head/ear surgeries, or use medical implants, check with us and your provider first. We will recommend a private session or modified practice when appropriate.</div>
          </details>

          <details>
            <summary>Can I record sessions?</summary>
            <div class="small">Recordings are not permitted during live, in-person cohorts to protect the shared container. Cohort leaders may provide short recorded recaps or practice snippets for cohort members.</div>
          </details>

          <details>
            <summary>Refunds and transfers</summary>
            <div class="small">If you need to cancel, please contact us as soon as possible. Cohort passes may be transferable to another named attendee with notice. Refund policies vary by program; see the Investment page for specifics or contact us directly.</div>
          </details>

          <div class="contra">
            <strong>Contraindications & safety</strong>
            <p class="small">Sound immersion can be relaxing and potent. If you live with severe anxiety, PTSD, epilepsy, or have had recent inner-ear or cranial surgery, please reach out before enrolling. If you are pregnant and concerned about sensations, get medical guidance first. We will always suggest safer formats — a private session, an alternative guide, or additional supports.</p>
          </div>
        </div>

      </div>

      <aside class="aside">
        <div style="background:rgba(255,255,255,0.02);padding:16px;border-radius:12px">
          <strong style="display:block;color:#dff7f2">Quick links</strong>
          <div style="margin-top:8px"><a href="events.html" style="color:#9eeedf;text-decoration:none">See upcoming gatherings</a></div>
          <div style="margin-top:6px"><a href="book.html" style="color:#9eeedf;text-decoration:none">Reserve a spot</a></div>
          <div style="margin-top:6px;color:var(--muted)">Prefer phone? Call {{PHONE}}</div>
          <a class="cta" href="book.html">Book now</a>
        </div>

        <div style="margin-top:16px;background:rgba(255,255,255,0.02);padding:12px;border-radius:10px">
          <strong style="color:#dff7f2">Health & access</strong>
          <p class="small" style="margin-top:8px">If mobility, sensory processing, or a medical condition affects your participation, contact us before your arrival so we can prepare a supportive environment.</p>
        </div>
      </aside>
    </div>
  </main>

  <footer>
    <div style="max-width:900px;margin:0 auto;color:var(--muted)">Need more detail? Email <a href="mailto:{{EMAIL}}" style="color:#9eeedf">{{EMAIL}}</a> or call {{PHONE}}. Sessions located in {{CITY}}, {{STATE}}.</div>
  </footer>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#041021;--muted:#9bb4b1;--accent:#7ce3d6;--card:#07202a}
    body{margin:0;font-family:Inter,system-ui,Roboto,Arial;color:#e9fbf6;background:linear-gradient(180deg,#031018 0%,#041723 100%)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 22px}
    .logo{font-weight:800;padding:8px 12px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#6fb8ff);color:#042028}
    nav a{margin-left:10px;color:#bfeee6;text-decoration:none}
    main{max-width:1100px;margin:18px auto;padding:0 20px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:20px}
    .booking{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px}
    .panel{background:rgba(255,255,255,0.02);padding:16px;border-radius:10px;margin-bottom:12px}
    label{display:block;margin-top:10px;color:var(--muted);font-weight:700}
    input,select{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);margin-top:6px;background:transparent;color:#e8f8f4}
    .toggle{display:flex;gap:8px;background:rgba(255,255,255,0.01);padding:8px;border-radius:10px}
    .toggle button{flex:1;padding:10px;border-radius:8px;border:0;background:transparent;color:var(--muted);cursor:pointer}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),#6fb8ff);color:#042028}
    .price-big{font-size:36px;font-weight:800;color:#dff7f2}
    .muted{color:var(--muted)}
    .reserve-cta{display:inline-block;padding:12px 16px;border-radius:10px;background:var(--accent);color:#042028;text-decoration:none;font-weight:800;margin-top:12px}
    .small{font-size:13px;color:var(--muted)}
    footer{padding:22px;text-align:center;color:var(--muted)}
    @media(max-width:980px){.grid{grid-template-columns:1fr}.nav{display:none}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">{{BUSINESS_NAME}}</div>
      <div style="color:#9edfd3;font-size:13px">Reserve a cohort seat or a short private plan</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Our Story</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <div class="booking">
        <h2 style="margin:0 0 6px 0;color:#dff7f2">Reserve your spot</h2>
        <p class="small">Choose the format that fits your schedule: one-off cohort drops, short WaveSeries, or a private short plan.</p>

        <div class="panel">
          <label>Program type</label>
          <select id="program-type">
            <option value="drop">Drop-in Cohort — single session</option>
            <option value="wave">WaveSeries — 5-session pass</option>
            <option value="private">Private short plan — 3 sessions</option>
          </select>

          <label style="margin-top:12px">Date preference</label>
          <input type="date" id="date-prefer">

          <div style="margin-top:12px">
            <label>Number of seats</label>
            <input type="number" id="seats" min="1" value="1">
          </div>
        </div>

        <div class="panel">
          <label>Pricing view</label>
          <div class="toggle" id="pricing-toggle">
            <button data-mode="monthly" class="active">Monthly</button>
            <button data-mode="package">Package</button>
          </div>

          <div style="display:flex;align-items:center;justify-content:space-between;margin-top:12px">
            <div>
              <div class="muted">Your rate</div>
              <div class="price-big" id="price-value">$35</div>
              <div class="small muted" id="price-sub">per drop-in</div>
            </div>
            <div style="text-align:right">
              <div class="small muted">Program</div>
              <div style="font-weight:700;color:#dff7f2" id="price-program">Drop-in Cohort</div>
            </div>
          </div>

          <div style="margin-top:10px;color:var(--muted);font-size:13px">Use the toggle to compare a monthly subscription vs a package pass. Numbers animate for clarity.</div>
        </div>

        <div class="panel">
          <strong style="display:block;color:#dff7f2">Mood-to-Method selector</strong>
          <p class="small">Pick how you feel and we'll suggest the right format and update the CTA.</p>
          <div style="display:flex;gap:8px;margin-top:10px" id="book-moods">
            <button data-key="worn" style="flex:1;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted)">Worn</button>
            <button data-key="frenzy" style="flex:1;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted)">Frenzy</button>
            <button data-key="stuck" style="flex:1;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted)">Stuck</button>
            <button data-key="seeking" style="flex:1;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted)">Seeking</button>
          </div>

          <div style="margin-top:12px;background:rgba(255,255,255,0.01);padding:12px;border-radius:8px">
            <div id="book-reco" style="font-weight:700;color:#dff7f2">Recommend: Drop-in Cohort — 45 min</div>
            <div id="book-desc" class="small muted" style="margin-top:8px">A short, focused session to recalibrate.</div>
            <a id="book-cta" class="reserve-cta" href="{{PRIMARY_CTA_URL}}">Reserve this</a>
          </div>
        </div>

      </div>

      <aside>
        <div style="background:rgba(255,255,255,0.02);padding:16px;border-radius:12px">
          <strong style="color:#dff7f2">Quick booking</strong>
          <p class="small" style="margin-top:8px">Call {{PHONE}} or email <a href="mailto:{{EMAIL}}" style="color:#9eeedf">{{EMAIL}}</a> for group bookings or accessibility needs.</p>
          <div style="margin-top:12px">
            <div style="font-weight:800;color:#dff7f2;font-size:14px">PulsePass — 5 sessions</div>
            <div class="small muted">Flexible series pass. Use over 3 months.</div>
          </div>
          <div style="margin-top:12px">
            <div style="font-weight:800;color:#dff7f2;font-size:14px">FlowMonthly — subscription</div>
            <div class="small muted">Monthly access to drop-ins and cohort priority booking.</div>
          </div>
        </div>

        <div style="margin-top:12px;background:rgba(255,255,255,0.02);padding:12px;border-radius:10px">
          <strong style="color:#dff7f2">Important</strong>
          <p class="small muted" style="margin-top:8px">If you have epilepsy, recent ear/head surgery, or implants, please consult your clinician before booking. For questions, contact us.</p>
        </div>
      </aside>
    </div>
  </main>

  <footer>
    <div style="color:var(--muted)">Thanks for choosing a mindful break. For venue questions: {{CITY}}, {{STATE}} — phone {{PHONE}}.</div>
  </footer>

  <script>
    ;(function(){
      // Pricing comparator
      const toggle = document.getElementById('pricing-toggle');
      const buttons = toggle.querySelectorAll('button');
      const priceValue = document.getElementById('price-value');
      const priceSub = document.getElementById('price-sub');
      const priceProgram = document.getElementById('price-program');

      // base prices
      const rates = {
        drop: {monthly:35, package:150, labelMonthly:'per drop-in', labelPackage:'per 5-session pass'},
        wave: {monthly:28, package:125, labelMonthly:'per session (WaveSeries)', labelPackage:'per 5-session pass'},
        private: {monthly:120, package:320, labelMonthly:'per session (private)', labelPackage:'3-session plan'}
      };

      let mode = 'monthly';

      function animateNumber(el, start, end, suffix=''){
        const dur = 500; const startTime = performance.now();
        (function tick(now){
          const t = Math.min(1,(now-startTime)/dur);
          const v = Math.round(start + (end-start)*t);
          el.textContent = '$' + v + (suffix?(' ' + suffix):'');
          if(t<1) requestAnimationFrame(tick);
        })(performance.now());
      }

      function refreshPrice(){
        const program = document.getElementById('program-type').value;
        const seats = Math.max(1, parseInt(document.getElementById('seats').value||1));
        const r = rates[program][mode];
        const label = (mode==='monthly') ? rates[program].labelMonthly : rates[program].labelPackage;
        const perUnit = Math.round(r);
        animateNumber(priceValue, parseInt(priceValue.textContent.replace(/[^0-9]/g,''))||0, perUnit * seats, '');
        priceSub.textContent = label;
        priceProgram.textContent = (program==='drop')? 'Drop-in Cohort' : (program==='wave')? 'WaveSeries' : 'Private plan';
      }

      buttons.forEach(b=>b.addEventListener('click',()=>{
        buttons.forEach(x=>x.classList.remove('active'));
        b.classList.add('active');
        mode = b.dataset.mode;
        refreshPrice();
      }));

      document.getElementById('program-type').addEventListener('change',refreshPrice);
      document.getElementById('seats').addEventListener('input',refreshPrice);

      // init
      priceValue.textContent = '$35';

      // Mood-to-Method for booking
      const moods = document.getElementById('book-moods');
      const reco = document.getElementById('book-reco');
      const desc = document.getElementById('book-desc');
      const bookCta = document.getElementById('book-cta');

      const moodMap = {
        worn:{rec:'Drop-in Cohort — 45 min',desc:'Calm-paced sound to ease weariness.',cta:'Reserve a Resting Drop-in',program:'drop'},
        frenzy:{rec:'Pulse Pause — 30 min',desc:'A condensed reset to interrupt a busy loop.',cta:'Reserve a Pulse Pause',program:'drop'},
        stuck:{rec:'Anchor WaveSeries — 5 sessions',desc:'Short-series to shift patterns over time.',cta:'Join an Anchor Wave',program:'wave'},
        seeking:{rec:'Private short plan — 3 sessions',desc:'Tailored support to explore deeper adjustments.',cta:'Request a Private Plan',program:'private'}
      };

      moods.querySelectorAll('button').forEach(btn=>btn.addEventListener('click',()=>{
        moods.querySelectorAll('button').forEach(b=>b.style.background='transparent');
        btn.style.background='linear-gradient(90deg,var(--accent),#6fb8ff)';
        const k = btn.dataset.key;
        const m = moodMap[k];
        reco.textContent = 'Recommend: ' + m.rec;
        desc.textContent = m.desc;
        bookCta.textContent = m.cta;
        // update form selections to match suggestion
        document.getElementById('program-type').value = m.program;
        // also update pricing view
        refreshPrice();
        // CTA link goes to primary with focus query
        bookCta.href = '{{PRIMARY_CTA_URL}}?focus=' + encodeURIComponent(k);
      }));

      // default mood
      moods.querySelector('button').click();
    })();
  </script>
</body>
